using System.Text.Json;using Microsoft.EntityFrameworkCore;using Moq;using SenorArroz.Application.Common.Interfaces;using SenorArroz.Application.Features.WhatsApp.DTOs;using SenorArroz.Domain.Entities;using SenorArroz.Domain.Enums;using SenorArroz.Domain.Services;using SenorArroz.Infrastructure.Data;using SenorArroz.Infrastructure.Services;
namespace SenorArroz.Tests;
public class HumanAssistanceAgentToolTests
{
 [Fact]public async Task RequestHuman_ChangesModeNotifiesAndUsesConfiguredMessage(){await using var db=Db();db.WhatsAppConversations.Add(new WhatsAppConversation{Id=1,BranchId=1,PhoneNumber="300",AttentionMode=WhatsAppAttentionMode.Ai});db.WhatsAppMessages.Add(new WhatsAppMessage{Id=10,ConversationId=1,Direction=WhatsAppMessageDirection.Inbound,Type=WhatsAppMessageType.Text,TextBody="asesor",Status=WhatsAppMessageStatus.Received,Timestamp=DateTime.UtcNow});db.BranchAiSettings.Add(new BranchAiSetting{BranchId=1,TransferMessage="Ya te comunicamos con un asesor."});await db.SaveChangesAsync();var notifications=new Mock<IWhatsAppNotificationService>();var sender=new Mock<IWhatsAppAutomaticMessageSender>();sender.Setup(x=>x.SendTransferTextAsync(1,10,It.IsAny<string>(),"Ya te comunicamos con un asesor.",It.IsAny<CancellationToken>())).ReturnsAsync(new WhatsAppAutomaticSendResult(true,false,"wamid",null));var clock=new Mock<IClock>();clock.SetupGet(x=>x.UtcNow).Returns(DateTime.UtcNow);using var args=JsonDocument.Parse("""{"reason":"El cliente solicita asesor"}""");var result=await new RequestHumanAssistanceAgentTool(db,new WhatsAppAttentionService(),notifications.Object,sender.Object,clock.Object).ExecuteAsync(new(1,1,10,ExecutionId:"run"),args.RootElement,default);Assert.True(result.TransferredToHuman);Assert.Equal(WhatsAppAttentionMode.WaitingForHuman,(await db.WhatsAppConversations.FindAsync(1))!.AttentionMode);notifications.Verify(x=>x.NotifyAttentionChangedAsync(1,It.IsAny<WhatsAppConversationDto>(),It.IsAny<CancellationToken>()),Times.Once);sender.VerifyAll();}
 private static ApplicationDbContext Db()=>new(new DbContextOptionsBuilder<ApplicationDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);
}
